// See the file "COPYING" in the main distribution directory for copyright.

#include "zeek/analyzer/protocol/smb/SMB.h"

namespace zeek::analyzer::smb {

// This was 1<<17 originally but was changed due to larger messages
// being seen.
#define SMB_MAX_LEN (1 << 18)

SMB_Analyzer::SMB_Analyzer(Connection* conn) : analyzer::tcp::TCP_ApplicationAnalyzer("SMB", conn) {
    chunks = 0;
    interp = new binpac::SMB::SMB_Conn(this);
    need_sync = true;
}

SMB_Analyzer::~SMB_Analyzer() { delete interp; }

void SMB_Analyzer::Done() {
    TCP_ApplicationAnalyzer::Done();

    interp->FlowEOF(true);
    interp->FlowEOF(false);
}

void SMB_Analyzer::EndpointEOF(bool is_orig) {
    TCP_ApplicationAnalyzer::EndpointEOF(is_orig);

    interp->FlowEOF(is_orig);
}

void SMB_Analyzer::Undelivered(uint64_t seq, int len, bool orig) {
    TCP_ApplicationAnalyzer::Undelivered(seq, len, orig);

    NeedResync();
}

bool SMB_Analyzer::HasSMBHeader(int len, const u_char* data) {
    if ( len < 8 )
        return false;

    return (strncmp(reinterpret_cast<const char*>(data) + 4, "\xffSMB", 4) == 0 ||
            strncmp(reinterpret_cast<const char*>(data) + 4, "\xfeSMB", 4) == 0);
}

void SMB_Analyzer::NeedResync() {
    interp->upflow()->flow_buffer()->DiscardData();
    interp->downflow()->flow_buffer()->DiscardData();
    need_sync = true;
}

void SMB_Analyzer::DeliverStream(int len, const u_char* data, bool orig) {
    TCP_ApplicationAnalyzer::DeliverStream(len, data, orig);

    // It we need to resync and we don't have an SMB header, bail!
    if ( need_sync && ! HasSMBHeader(len, data) )
        return;
    else
        need_sync = false;

    try {
        // If we get here, it means we have an SMB header in the message.
        interp->NewData(orig, data, data + len);

        // Let's assume that if there are no binpac exceptions after
        // 3 data chunks that this is probably actually SMB.
        if ( ++chunks == 3 )
            AnalyzerConfirmation();
    } catch ( const binpac::Exception& e ) {
        AnalyzerViolation(util::fmt("Binpac exception: %s", e.what()));
        NeedResync();
    }
}

} // namespace zeek::analyzer::smb

enum smb3_capabilities {
	SMB2_GLOBAL_CAP_DFS                   = 0x00,
	SMB2_GLOBAL_CAP_LEASING               = 0x02,
	SMB2_GLOBAL_CAP_LARGE_MTU             = 0x04,
	SMB2_GLOBAL_CAP_MULTI_CHANNEL         = 0x08,
	SMB2_GLOBAL_CAP_PERSISTENT_HANDLES    = 0x10,
	SMB2_GLOBAL_CAP_DIRECTORY_LEASING     = 0x20,
	SMB2_GLOBAL_CAP_ENCRYPTION            = 0x40,
};

enum smb3_context_type {
	SMB2_PREAUTH_INTEGRITY_CAPABILITIES   = 0x0001,
	SMB2_ENCRYPTION_CAPABILITIES          = 0x0002,
	SMB2_COMPRESSION_CAPABILITIES         = 0x0003,
	SMB2_NETNAME_NEGOTIATE_CONTEXT_ID     = 0x0005,
};


refine connection SMB_Conn += {

	function proc_smb2_negotiate_request(h: SMB2_Header, val: SMB2_negotiate_request) : bool
		%{
		if ( smb2_negotiate_request )
			{
			auto dialects = zeek::make_intrusive<zeek::VectorVal>(zeek::id::index_vec);

			for ( unsigned int i = 0; i < ${val.dialects}->size(); ++i )
				dialects->Assign(i, zeek::val_mgr->Count((*${val.dialects})[i]));

			zeek::BifEvent::enqueue_smb2_negotiate_request(zeek_analyzer(), zeek_analyzer()->Conn(),
			                                         BuildSMB2HeaderVal(h),
			                                         std::move(dialects));
			}

		return true;
		%}

	function proc_smb2_negotiate_response(h: SMB2_Header, val: SMB2_negotiate_response) : bool
		%{
		if ( smb2_negotiate_response )
			{
			auto nr = zeek::make_intrusive<zeek::RecordVal>(zeek::BifType::Record::SMB2::NegotiateResponse);

			nr->Assign(0, ${val.dialect_revision});
			nr->Assign(1, ${val.security_mode});
			nr->Assign(2, BuildSMB2GUID(${val.server_guid}));
			nr->Assign(3, filetime2zeektime(${val.system_time}));
			nr->Assign(4, filetime2zeektime(${val.server_start_time}));
			nr->Assign(5, ${val.negotiate_context_count});

			auto cv = zeek::make_intrusive<zeek::VectorVal>(zeek::BifType::Vector::SMB2::NegotiateContextValues);

			if ( ${val.dialect_revision} == 0x0311 && ${val.negotiate_context_count} > 0 )
				{
				for ( auto i = 0u; i < ${val.smb3_ncl.list.vals}->size(); ++i )
					cv->Assign(i, BuildSMB2ContextVal(${val.smb3_ncl.list.vals[i].ncv}));

				cv->Assign(${val.smb3_ncl.list.vals}->size(), BuildSMB2ContextVal(${val.smb3_ncl.list.last_val}));
				}

			nr->Assign(6, std::move(cv));

			zeek::BifEvent::enqueue_smb2_negotiate_response(zeek_analyzer(), zeek_analyzer()->Conn(),
			                                                BuildSMB2HeaderVal(h),
			                                                std::move(nr));
			}

		return true;
		%}
};

type SMB3_preauth_integrity_capabilities = record {
	hash_alg_count    	: uint16;
	salt_length     	: uint16;
	hash_alg		: uint16[hash_alg_count];
	salt			: bytestring &length = salt_length;
};

type SMB3_encryption_capabilities = record {
	cipher_count    	: uint16;
	ciphers			: uint16[cipher_count];
};

type SMB3_compression_capabilities = record {
	alg_count : uint16;
	pad:        uint16;
	reserved  : uint32;
	algs      : uint16[alg_count];
};

type SMB3_netname_negotiate_context_id(len: uint16) = record {
	net_name: bytestring &length = len;
};

type SMB3_negotiate_context_value = record {
	context_type    	: uint16;          # specify the type of context
	data_length     	: uint16;          # the length of the data field
	reserved		: uint32;	   # ignored
	data			: case context_type of {
		SMB2_PREAUTH_INTEGRITY_CAPABILITIES   -> preauth_integrity_capabilities : SMB3_preauth_integrity_capabilities;
		SMB2_ENCRYPTION_CAPABILITIES          -> encryption_capabilities        : SMB3_encryption_capabilities;
		SMB2_COMPRESSION_CAPABILITIES         -> compression_capabilities       : SMB3_compression_capabilities;
		SMB2_NETNAME_NEGOTIATE_CONTEXT_ID     -> netname_negotiate_context_id   : SMB3_netname_negotiate_context_id(data_length);
		default                               -> unknown_context_data           : bytestring &length=data_length;
	};
};

type Padded_SMB3_negotiate_context_value = record {
	ncv: SMB3_negotiate_context_value;
	pad: padding align 8;
};

type SMB2_negotiate_request(header: SMB2_Header) = record {
	structure_size    	: uint16;          # client MUST set this to 36
	dialect_count     	: uint16;          # must be > 0
	security_mode     	: uint16;          # there is a list of required modes
	reserved          	: padding[2];      # must be set to 0
	capabilities      	: uint32;          # must be set to 0 if SMB 2.x, otherwise if SMB 3.x one of enum smb2_capabilities
	client_guid       	: SMB2_guid;       # guid if client implements SMB 2.1 dialect, otherwise set to 0
	client_start_time 	: SMB_timestamp;
	dialects          : uint16[dialect_count];
} &byteorder=littleendian, &let {
	proc : bool = $context.connection.proc_smb2_negotiate_request(header, this);
};

type NegotiateContextList(len: uint16) = record {
	vals: Padded_SMB3_negotiate_context_value[len - 1];
	last_val: SMB3_negotiate_context_value;
};

type OptNegotiateContextList(len: uint16) = record {
	opt: case len of {
		0 -> nil: empty;
		default -> list: NegotiateContextList(len);
	};
};

type SMB2_negotiate_response(header: SMB2_Header) = record {
	structure_size            : uint16;
	security_mode             : uint16;
	dialect_revision          : uint16;
	negotiate_context_count   : uint16;	# reserved to 0 if not smb 3.1.1
	server_guid               : SMB2_guid;
	capabilities              : uint32;
	max_transact_size         : uint32;
	max_read_size             : uint32;
	max_write_size            : uint32;
	system_time               : SMB_timestamp;
	server_start_time         : SMB_timestamp;
	security_offset           : uint16;
	security_length           : uint16;
	negotiate_context_offset  : uint32;
	security_blob             : bytestring &length=security_length;
	pad1                      : padding to (dialect_revision == 0x0311 ? negotiate_context_offset - header.head_length : 0);
	negotiate_context_list    : case dialect_revision of {
		0x0311    -> smb3_ncl : OptNegotiateContextList(negotiate_context_count);
		default   -> unknown  : empty;
	};
} &byteorder=littleendian, &let {
	proc : bool = $context.connection.proc_smb2_negotiate_response(header, this);
	gssapi_proc : bool = $context.connection.forward_gssapi(security_blob, false);

};

--- transform ---
refine connection SMB_Conn += {

	function proc_smb2_transform_header(hdr: SMB2_transform_header) : bool
		%{
		if ( smb2_transform_header )
			{
			auto r = zeek::make_intrusive<zeek::RecordVal>(zeek::BifType::Record::SMB2::Transform_header);
			r->Assign(0, to_stringval(${hdr.signature}));
			r->Assign(1, to_stringval(${hdr.nonce}));
			r->Assign(2, ${hdr.orig_msg_size});
			r->Assign(3, ${hdr.flags});
			r->Assign(4, ${hdr.session_id});

			zeek::BifEvent::enqueue_smb2_transform_header(zeek_analyzer(),
			                                        zeek_analyzer()->Conn(),
			                                        std::move(r));
			}

		return true;
		%}

};

type SMB2_transform_header = record {
	signature         : bytestring &length = 16;
	nonce             : bytestring &length = 16;
	orig_msg_size     : uint32;
	reserved          : uint16;
	flags             : uint16;
	session_id	  : uint64;
} &let {
	proc: bool = $context.connection.proc_smb2_transform_header(this);
} &byteorder = littleendian;

--- protocol ---
# Documentation for SMB2 protocol from here:
#     https://msdn.microsoft.com/en-us/library/cc246497(v=PROT.13).aspx

%header{
zeek::RecordValPtr BuildSMB2HeaderVal(SMB2_Header* hdr);
zeek::RecordValPtr BuildSMB2GUID(SMB2_guid* file_id);
zeek::RecordValPtr smb2_file_attrs_to_zeek(SMB2_file_attributes* val);
zeek::RecordValPtr BuildSMB2ContextVal(SMB3_negotiate_context_value* ncv);
%}

%code{
zeek::RecordValPtr BuildSMB2HeaderVal(SMB2_Header* hdr)
	{
	auto r = zeek::make_intrusive<zeek::RecordVal>(zeek::BifType::Record::SMB2::Header);
	r->Assign(0, ${hdr.credit_charge});
	r->Assign(1, ${hdr.status});
	r->Assign(2, ${hdr.command});
	r->Assign(3, ${hdr.credits});
	r->Assign(4, ${hdr.flags});
	r->Assign(5, ${hdr.message_id});
	r->Assign(6, ${hdr.process_id});
	r->Assign(7, ${hdr.tree_id});
	r->Assign(8, ${hdr.session_id});
	r->Assign(9, to_stringval(${hdr.signature}));
	return r;
	}

zeek::RecordValPtr BuildSMB2GUID(SMB2_guid* file_id)
	{
	auto r = zeek::make_intrusive<zeek::RecordVal>(zeek::BifType::Record::SMB2::GUID);
	r->Assign(0, ${file_id.persistent});
	r->Assign(1, ${file_id._volatile});
	return r;
	}

zeek::RecordValPtr smb2_file_attrs_to_zeek(SMB2_file_attributes* val)
	{
	auto r = zeek::make_intrusive<zeek::RecordVal>(zeek::BifType::Record::SMB2::FileAttrs);
	r->Assign(0, ${val.read_only});
	r->Assign(1, ${val.hidden});
	r->Assign(2, ${val.system});
	r->Assign(3, ${val.directory});
	r->Assign(4, ${val.archive});
	r->Assign(5, ${val.normal});
	r->Assign(6, ${val.temporary});
	r->Assign(7, ${val.sparse_file});
	r->Assign(8, ${val.reparse_point});
	r->Assign(9, ${val.compressed});
	r->Assign(10, ${val.offline});
	r->Assign(11, ${val.not_content_indexed});
	r->Assign(12, ${val.encrypted});
	r->Assign(13, ${val.integrity_stream});
	r->Assign(14, ${val.no_scrub_data});
	return r;
	}

zeek::RecordValPtr BuildSMB2ContextVal(SMB3_negotiate_context_value* ncv)
	{
	auto r = zeek::make_intrusive<zeek::RecordVal>(zeek::BifType::Record::SMB2::NegotiateContextValue);

	r->Assign(0, ${ncv.context_type});
	r->Assign(1, ${ncv.data_length});

	switch ( ${ncv.context_type} ) {
	case SMB2_PREAUTH_INTEGRITY_CAPABILITIES:
		{
		auto rpreauth = zeek::make_intrusive<zeek::RecordVal>(zeek::BifType::Record::SMB2::PreAuthIntegrityCapabilities);
		rpreauth->Assign(0, ${ncv.preauth_integrity_capabilities.hash_alg_count});
		rpreauth->Assign(1, ${ncv.preauth_integrity_capabilities.salt_length});

		auto ha = zeek::make_intrusive<zeek::VectorVal>(zeek::id::index_vec);

		for ( int i = 0; i < ${ncv.preauth_integrity_capabilities.hash_alg_count}; ++i )
			{
			const auto& vec = *${ncv.preauth_integrity_capabilities.hash_alg};
			ha->Assign(i, zeek::val_mgr->Count(vec[i]));
			}

		rpreauth->Assign(2, std::move(ha));
		rpreauth->Assign(3, to_stringval(${ncv.preauth_integrity_capabilities.salt}));
		r->Assign(2, std::move(rpreauth));
		}
		break;

	case SMB2_ENCRYPTION_CAPABILITIES:
		{
		auto rencr = zeek::make_intrusive<zeek::RecordVal>(zeek::BifType::Record::SMB2::EncryptionCapabilities);
		rencr->Assign(0, ${ncv.encryption_capabilities.cipher_count});

		auto c = zeek::make_intrusive<zeek::VectorVal>(zeek::id::index_vec);

		for ( int i = 0; i < ${ncv.encryption_capabilities.cipher_count}; ++i )
			{
			const auto& vec = *${ncv.encryption_capabilities.ciphers};
			c->Assign(i, zeek::val_mgr->Count(vec[i]));
			}

		rencr->Assign(1, std::move(c));
		r->Assign(3, std::move(rencr));
		}
		break;

	case SMB2_COMPRESSION_CAPABILITIES:
		{
		auto rcomp = zeek::make_intrusive<zeek::RecordVal>(zeek::BifType::Record::SMB2::CompressionCapabilities);
		rcomp->Assign(0, ${ncv.compression_capabilities.alg_count});

		auto c = zeek::make_intrusive<zeek::VectorVal>(zeek::id::index_vec);

		for ( int i = 0; i < ${ncv.compression_capabilities.alg_count}; ++i )
			{
			const auto& vec = *${ncv.compression_capabilities.algs};
			c->Assign(i, zeek::val_mgr->Count(vec[i]));
			}

		rcomp->Assign(1, std::move(c));
		r->Assign(4, std::move(rcomp));
		}
		break;

	case SMB2_NETNAME_NEGOTIATE_CONTEXT_ID:
		{
		r->Assign(5, to_stringval(${ncv.netname_negotiate_context_id.net_name}));
		}
		break;

	default:
		break;
	}

	return r;
	}
